use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::{AgentResponse, LlmError};

struct Node;

const MAX_ROUNDS: usize = 3;

fn intent_label(i: Intent) -> &'static str {
    match i {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system = format!(
            "You are a customer support assistant. Intent: {}. \
             Answer the customer's question using the provided knowledge. \
             You may request the 'lookup' tool for more knowledge.",
            intent_label(ctx.intent)
        );

        let mut knowledge: Vec<String> = ctx.knowledge.clone();
        for entry in kb_read::lookup(&ctx.question) {
            if !knowledge.contains(&entry) {
                knowledge.push(entry);
            }
        }

        let build_prompt = |knowledge: &[String]| {
            let mut p = String::new();
            p.push_str("Question:\n");
            p.push_str(&ctx.question);
            p.push_str("\n\nKnowledge:\n");
            for k in knowledge {
                p.push_str("- ");
                p.push_str(k);
                p.push('\n');
            }
            p
        };

        for _ in 0..MAX_ROUNDS {
            let prompt = build_prompt(&knowledge);
            match tool_llm::generate(&system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not permitted: {}", req.tool),
                        });
                    }
                    for entry in kb_read::lookup(&req.query) {
                        if !knowledge.contains(&entry) {
                            knowledge.push(entry);
                        }
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "no answer produced within tool-call limit".to_string(),
        })
    }
}

export!(Node);
